style.css:
@-moz-document domain("youtube.com") {
/* PALETA: personalize estas cores */
  :root {
    --my-bg: #100d19;
    --my-panel: #1a1428;
    --my-raised: #261b38;
    --my-purple: #8254bd;
    --my-purple-deep: #312047;
    --my-green: #a8f542;
    --my-orange: #ff902f;
    --my-red: #ff5064;
    --my-text: #f3effb;
    --my-muted: #bab0ca;
    --my-border: #59416e;
    --my-glow: rgba(168, 245, 66, .22);
    --my-speed: 320ms;
  }

  /* MODO CLARO: laboratório NERV */
  html:not([dark]) {
    --my-bg: #f0edf5;
    --my-panel: #fffaff;
    --my-raised: #e7deef;
    --my-purple: #684093;
    --my-purple-deep: #dcd0e9;
    --my-green: #527e12;
    --my-orange: #ad4b00;
    --my-red: #ba2945;
    --my-text: #21172f;
    --my-muted: #665a75;
    --my-border: #bcaace;
    --my-glow: rgba(82, 126, 18, .16);
  }

  /* CORES NATIVAS DO YOUTUBE */
  html,
  html[dark],
  ytd-app {
    --yt-spec-base-background: var(--my-bg) !important;
    --yt-spec-general-background-a: var(--my-bg) !important;
    --yt-spec-general-background-b: var(--my-panel) !important;
    --yt-spec-general-background-c: var(--my-raised) !important;
    --yt-spec-raised-background: var(--my-panel) !important;
    --yt-spec-menu-background: var(--my-panel) !important;
    --yt-spec-text-primary: var(--my-text) !important;
    --yt-spec-text-secondary: var(--my-muted) !important;
    --yt-spec-icon-inactive: var(--my-muted) !important;
    --yt-spec-icon-active: var(--my-green) !important;
    --yt-spec-brand-icon-active: var(--my-green) !important;
    --yt-spec-static-brand-red: var(--my-orange) !important;
    --yt-spec-outline: var(--my-border) !important;
  }

  /* FUNDO: grade técnica e iluminação */
  html,
  body,
  ytd-app {
    color: var(--my-text) !important;
    font-family:
      "Arial Narrow",
      "Roboto Condensed",
      "Segoe UI",
      sans-serif !important;
    background-color: var(--my-bg) !important;
  }

  ytd-app {
    background-image:
      radial-gradient(
        ellipse at 85% 5%,
        rgba(130, 84, 189, .15),
        transparent 48%
      ),
      linear-gradient(
        rgba(130, 84, 189, .045) 1px,
        transparent 1px
      ),
      linear-gradient(
        90deg,
        rgba(130, 84, 189, .045) 1px,
        transparent 1px
      ) !important;
    background-size:
      100% 100%,
      38px 38px,
      38px 38px !important;
    background-attachment: fixed !important;
  }

  /* CABEÇALHO: console NERV */
  ytd-masthead,
  #background.ytd-masthead {
    background: linear-gradient(
      110deg,
      var(--my-bg),
      var(--my-purple-deep) 65%,
      var(--my-bg)
    ) !important;
    border-bottom: 2px solid var(--my-green) !important;
    box-shadow:
      0 3px 22px var(--my-glow),
      inset 0 -1px var(--my-purple) !important;
  }

  ytd-masthead {
    animation: my-header-entry 650ms ease-out both;
  }

  ytd-masthead #logo {
    position: relative !important;
  }

  ytd-masthead #logo::after {
    content: "NERV / 01";
    position: absolute;
    top: -10px;
    left: 0;
    font: 700 9px monospace;
    letter-spacing: 2px;
    color: var(--my-green);
    pointer-events: none;
  }

  /* PESQUISA: painel de comando */
  #container.ytd-searchbox,
  ytd-searchbox #container {
    background: var(--my-panel) !important;
    border: 1px solid var(--my-border) !important;
    border-radius: 5px 0 0 5px !important;
    transition:
      border-color var(--my-speed),
      box-shadow var(--my-speed) !important;
  }

  #container.ytd-searchbox:focus-within,
  ytd-searchbox #container:focus-within {
    border-color: var(--my-green) !important;
    box-shadow: 0 0 16px var(--my-glow) !important;
  }

  #container.ytd-searchbox input,
  #search.ytd-searchbox {
    color: var(--my-text) !important;
    background: transparent !important;
    font-family: "Segoe UI", sans-serif !important;
  }

  #search-icon-legacy.ytd-searchbox {
    background: var(--my-purple-deep) !important;
    border: 1px solid var(--my-purple) !important;
    color: var(--my-green) !important;
    border-radius: 0 5px 5px 0 !important;
  }

  #search-icon-legacy.ytd-searchbox:hover {
    background: var(--my-green) !important;
    color: var(--my-bg) !important;
    box-shadow: 0 0 18px var(--my-glow) !important;
  }

  /* NAVEGAÇÃO LATERAL */
  #guide-content.ytd-app,
  ytd-mini-guide-renderer {
    background: var(--my-panel) !important;
    border-right: 1px solid var(--my-purple) !important;
  }

  #guide-section-title.ytd-guide-section-renderer {
    color: var(--my-orange) !important;
    font: 700 11px monospace !important;
    letter-spacing: 2px !important;
    text-transform: uppercase !important;
  }

  ytd-guide-entry-renderer,
  ytd-mini-guide-entry-renderer {
    transition:
      background var(--my-speed),
      transform var(--my-speed) !important;
  }

  ytd-guide-entry-renderer:hover,
  ytd-mini-guide-entry-renderer:hover {
    background: var(--my-raised) !important;
    transform: translateX(3px);
  }

  ytd-guide-entry-renderer[active],
  ytd-mini-guide-entry-renderer[active] {
    background: var(--my-purple-deep) !important;
    border-left: 3px solid var(--my-green) !important;
  }

  .guide-icon.ytd-guide-entry-renderer,
  .guide-icon.ytd-mini-guide-entry-renderer {
    color: var(--my-muted) !important;
  }

  ytd-guide-entry-renderer[active] .guide-icon,
  ytd-mini-guide-entry-renderer[active] .guide-icon {
    color: var(--my-green) !important;
  }

  /* FILTROS: módulos MAGI */
  #chips-wrapper.ytd-feed-filter-chip-bar-renderer,
  yt-chip-cloud-renderer {
    background: var(--my-bg) !important;
    border-bottom: 1px solid var(--my-border) !important;
  }

  yt-chip-cloud-chip-renderer {
    transition:
      transform 250ms,
      filter 250ms !important;
  }

  yt-chip-cloud-chip-renderer[chip-style][selected] {
    background: var(--my-green) !important;
    color: var(--my-bg) !important;
    border: 1px solid var(--my-green) !important;
    box-shadow: 0 0 13px var(--my-glow) !important;
  }

  yt-chip-cloud-chip-renderer:hover {
    transform: translateY(-2px);
    filter: brightness(1.13);
  }

  /* MINIATURAS: placas geométricas */
  ytd-thumbnail,
  ytd-rich-grid-media ytd-thumbnail {
    border-radius: 7px !important;
    overflow: hidden !important;
    outline: 1px solid var(--my-border) !important;
    outline-offset: -1px;
    transition:
      transform 400ms cubic-bezier(.2,.8,.2,1),
      outline-color 250ms,
      box-shadow 400ms !important;
  }

  ytd-thumbnail:hover {
    transform: translateY(-3px) scale(1.015);
    outline-color: var(--my-green) !important;
    box-shadow:
      0 0 0 1px var(--my-green),
      0 8px 25px var(--my-glow) !important;
  }

  /* TÍTULOS E IDENTIFICAÇÃO */
  #video-title,
  #video-title-link,
  h1.ytd-watch-metadata {
    color: var(--my-text) !important;
    font-weight: 650 !important;
    letter-spacing: .1px;
  }

  #video-title:hover,
  #video-title-link:hover {
    color: var(--my-green) !important;
  }

  #metadata-line,
  #metadata,
  #byline,
  #channel-name {
    color: var(--my-muted) !important;
  }

  /* CARTÕES: realce operacional */
  ytd-rich-grid-media,
  ytd-video-renderer,
  ytd-compact-video-renderer {
    transition:
      background 300ms,
      box-shadow 300ms !important;
  }

  ytd-rich-grid-media:hover,
  ytd-video-renderer:hover,
  ytd-compact-video-renderer:hover {
    background: rgba(130, 84, 189, .075) !important;
    box-shadow:
      inset 2px 0 var(--my-purple) !important;
  }

  /* REPRODUTOR: moldura da Unidade-01 */
  .html5-video-player {
    border: 1px solid var(--my-purple) !important;
    box-shadow:
      0 0 0 1px var(--my-bg),
      0 0 20px rgba(130, 84, 189, .16) !important;
  }

  .ytp-play-progress,
  .ytp-swatch-background-color {
    background: var(--my-green) !important;
  }

  .ytp-load-progress {
    background: var(--my-purple-deep) !important;
  }

  .ytp-volume-level {
    background: var(--my-orange) !important;
  }

  .ytp-scrubber-button {
    background: var(--my-green) !important;
    border: 2px solid var(--my-bg) !important;
    box-shadow: 0 0 12px var(--my-glow) !important;
  }

  .ytp-chrome-bottom {
    text-shadow: 0 1px 3px #000 !important;
  }

  /* BOTÕES E COMANDOS */
  ytd-watch-metadata button,
  yt-button-shape button {
    transition:
      transform 230ms,
      box-shadow 230ms,
      filter 230ms !important;
  }

  ytd-watch-metadata button:hover,
  yt-button-shape button:hover {
    transform: translateY(-2px);
    box-shadow:
      0 3px 13px var(--my-glow) !important;
  }

  ytd-subscribe-button-renderer button {
    border: 1px solid var(--my-green) !important;
    box-shadow:
      0 0 9px var(--my-glow) !important;
  }

  /* MENUS: terminais suspensos */
  ytd-menu-popup-renderer,
  ytd-multi-page-menu-renderer,
  tp-yt-paper-listbox,
  ytd-voice-search-dialog-renderer[dialog] {
    background: var(--my-panel) !important;
    color: var(--my-text) !important;
    border: 1px solid var(--my-purple) !important;
    border-radius: 5px !important;
    box-shadow:
      0 12px 32px rgba(0,0,0,.30),
      0 0 14px var(--my-glow) !important;
  }

  tp-yt-paper-item:hover,
  ytd-menu-service-item-renderer:hover {
    background: var(--my-raised) !important;
    color: var(--my-green) !important;
  }

  /* PLAYLISTS: arquivos MAGI */
  #container.ytd-playlist-panel-renderer,
  ytd-playlist-sidebar-renderer {
    background: var(--my-panel) !important;
    border: 1px solid var(--my-border) !important;
    border-radius: 5px !important;
  }

  .header.ytd-playlist-panel-renderer {
    background: var(--my-purple-deep) !important;
    border-bottom:
      2px solid var(--my-orange) !important;
  }

  .playlist-items.ytd-playlist-panel-renderer {
    background: var(--my-panel) !important;
  }

  /* COMENTÁRIOS: registros operacionais */
  ytd-comment-thread-renderer {
    border-left: 2px solid transparent !important;
    transition:
      border-color 300ms,
      background 300ms !important;
  }

  ytd-comment-thread-renderer:hover {
    border-left-color: var(--my-purple) !important;
    background:
      rgba(130, 84, 189, .06) !important;
  }

  /* DESTAQUE DE FOCO */
  a:focus-visible,
  button:focus-visible,
  input:focus-visible {
    outline: 2px solid var(--my-green) !important;
    outline-offset: 3px !important;
  }

  /* ANIMAÇÕES: inicialização do sistema */
  @keyframes my-header-entry {
    from {
      opacity: .5;
      transform: translateY(-14px);
    }
    to {
      opacity: 1;
      transform: translateY(0);
    }
  }

  @keyframes my-terminal-pulse {
    0%, 100% {
      box-shadow: 0 0 3px var(--my-glow);
    }
    50% {
      box-shadow: 0 0 17px var(--my-glow);
    }
  }

  @keyframes my-signal-entry {
    from {
      opacity: 0;
      transform: translateY(9px);
    }
    to {
      opacity: 1;
      transform: translateY(0);
    }
  }

  /* INDICADORES ATIVOS */
  ytd-guide-entry-renderer[active],
  yt-chip-cloud-chip-renderer[chip-style][selected] {
    animation:
      my-terminal-pulse 3.2s ease-in-out infinite;
  }

  /* ENTRADA DE PAINÉIS */
  ytd-menu-popup-renderer,
  ytd-multi-page-menu-renderer {
    animation: my-signal-entry 280ms ease-out;
  }

  /* ACESSIBILIDADE: movimento reduzido */
  @media (prefers-reduced-motion: reduce) {
    ytd-masthead,
    ytd-guide-entry-renderer[active],
    yt-chip-cloud-chip-renderer[chip-style][selected],
    ytd-menu-popup-renderer,
    ytd-multi-page-menu-renderer {
      animation: none !important;
    }
  }
}
